      ]
    },
    {
      "evidence_id": "evidence-meditation-experience-alerting-correlation--d4e5f6a7b8c9",
      "title": "Experience Predicts Alerting",
      "excerpt": "For retreat participants, months of meditation experience before the retreat were correlated with the magnitude of the Time 2 alerting score. The reported correlation was R=-.52 and was significant, t=2.4, p=.03, showing a significant reduction in alerting score with increased meditation experience.",
      "overview": "The correlation supports the idea that retreat-related alerting changes depended on prior meditation history rather than retreat attendance alone. It strengthens the paper's trajectory account in which receptive attention emerges after concentrative experience, but it remains correlational and confined to the retreat sample.",
      "evidence_type": "statistical_result",
